{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Mebendazole, a heteroaromatic amide/carbamate, has measured human absolute oral bioavailability of about 1% (with other estimates of 2-4%), demonstrating that polar heteroaromatic amide-containing molecules can have F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Rebamipide, an ionizable polar molecule containing amide and carboxylic acid groups, has human oral bioavailability under 10%, supporting low F for highly polar and ionizable compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Indacaterol, the closest Morgan analogue, has human oral bioavailability of approximately 24%, just above the threshold, but it is more lipophilic than the query due to dialkyl indane substituents, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "LY2196044, which contains both a primary carboxamide and a basic amine like the query, has absolute oral bioavailability of 45%, showing that such polar groups do not necessarily preclude F≥20%; however it has additional lipophilic aromatic/ether substituents absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low oral bioavailability (<20%) because the query is a strong base fully ionized at physiological pH with very low logD (-1.56) and moderate TPSA/HBD, indicating poor passive permeability. The closest experimental analogues are only weakly transferable (Morgan ~0.2), and the low-F evidence from polar/ionizable heteroaromatic drugs such as mebendazole and rebamipide outweighs the less transferable high-F basic-amine examples.",
  "evidence_gaps": [
    "No analogue with Morgan similarity above 0.25; all experimental evidence transfers weakly.",
    "No direct human PK or permeability data for the exact tetrahydrocarbazole carboxamide scaffold.",
    "Potential active uptake or efflux transporter effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

